`timescale 1ns / 1ps
// Repro for bucket DATA_ORDER: data bits must be sent least significant first.
module tb_uart_data_byte;
    localparam integer CPB = 4;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'd0;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    integer passed = 0;
    integer failed = 0;
    integer i;
    integer j;
    reg [8*64-1:0] nonce;
    reg [10:0] bits;
    reg [7:0]  got;
    reg [7:0]  vec [0:4];
    reg        done = 1'b0;

    task send_frame;
        input [7:0] d;
        begin
            @(negedge clk);
            data  = d;
            start = 1'b1;
            @(negedge tx);
            start = 1'b0;
            repeat (CPB / 2) @(posedge clk);
            #1 bits[0] = tx;
            for (i = 1; i < 11; i = i + 1) begin
                repeat (CPB) @(posedge clk);
                #1 bits[i] = tx;
            end
            wait (!busy);
            repeat (3) @(posedge clk);
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        vec[0] = 8'h01; vec[1] = 8'hD2; vec[2] = 8'h0F; vec[3] = 8'h80; vec[4] = 8'h35;
        repeat (4) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        repeat (2) @(posedge clk);
        for (j = 0; j < 5; j = j + 1) begin
            send_frame(vec[j]);
            if (bits[0] === 1'b0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("START_BIT: expected 0, got %b", bits[0]);
            end
            got = bits[8:1];
            if (got === vec[j]) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("DATA_ORDER: sent %h, received LSB-first %h", vec[j], got);
            end
        end
        done = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #200000;
        if (!done) begin
            done = 1'b1;
            failed = failed + 1;
            $display("WATCHDOG: timeout");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    end
endmodule
=== END FILE ===

