`timescale 1ns / 1ps
// Repro for bucket STOP_LENGTH: a frame must last 11 full bit times.
module tb_uart_frame_period;
    localparam integer CPB = 4;
    localparam integer FRAME = 11 * CPB;
    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'h5A;
    wire       tx;
    wire       busy;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    integer passed = 0;
    integer failed = 0;
    integer cnt;
    integer k;
    integer cyc;
    integer t_prev;
    integer t_now;
    reg [8*64-1:0] nonce;
    reg        done = 1'b0;

    // free-running cycle counter
    initial cyc = 0;
    always @(posedge clk) cyc = cyc + 1;

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
        repeat (4) @(posedge clk);
        @(negedge clk) rst = 1'b0;
        repeat (2) @(posedge clk);

        // Check 1: busy must cover a whole frame of 11 bit times.
        @(negedge clk) start = 1'b1;
        @(negedge clk) start = 1'b0;
        cnt = 0;
        while (busy === 1'b1) begin
            cnt = cnt + 1;
            @(negedge clk);
        end
        if (cnt >= FRAME) passed = passed + 1;
        else begin
            failed = failed + 1;
            $display("STOP_LENGTH: busy lasted %0d cycles, expected at least %0d", cnt, FRAME);
        end
        repeat (4) @(posedge clk);

        // Check 2: with start held high, frames must be at least 11 bit times apart.
        @(negedge clk) start = 1'b1;
        @(posedge busy);
        t_prev = cyc;
        for (k = 0; k < 3; k = k + 1) begin
            @(negedge busy);
            @(posedge busy);
            t_now = cyc;
            if ((t_now - t_prev) >= FRAME) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("STOP_LENGTH: frame period %0d cycles, expected at least %0d", t_now - t_prev, FRAME);
            end
            t_prev = t_now;
        end
        @(negedge clk) start = 1'b0;
        wait (!busy);
        repeat (3) @(posedge clk);

        done = 1'b1;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    initial begin
        #200000;
        if (!done) begin
            done = 1'b1;
            failed = failed + 1;
            $display("WATCHDOG: timeout");
            $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            $finish;
        end
    end
endmodule
=== END FILE ===

